# Metabolomics analysis
.met_req <- function(p){m<-p[!vapply(p,requireNamespace,logical(1),quietly=TRUE)];if(length(m))stop("Missing required R packages: ",paste(m,collapse=", "))}
.met_out <- function(p){if(dir.exists(p)&&length(list.files(p,all.files=TRUE,no..=TRUE)))stop("Output directory is not empty: ",p);dir.create(p,recursive=TRUE,showWarnings=FALSE);p}
.met_tmp <- function(p){if(!file.exists(p))stop("Input file not found: ",p);e<-tools::file_ext(p);z<-tempfile(fileext=if(nzchar(e))paste0(".",e)else"");if(!file.copy(p,z,overwrite=TRUE))stop("Failed to read input file: ",p);z}
.met_xlsx <- function(p){z<-.met_tmp(p);on.exit(unlink(z));as.data.frame(readxl::read_xlsx(z),check.names=FALSE)}
.met_csv <- function(p){z<-.met_tmp(p);on.exit(unlink(z));read.csv(z,check.names=FALSE,stringsAsFactors=FALSE)}
.met_pair <- function(x,s){write.csv(x,paste0(s,".csv"),row.names=FALSE,fileEncoding="UTF-8");openxlsx::write.xlsx(x,paste0(s,".xlsx"),overwrite=TRUE)}
.met_save <- function(p,s,w,h){ggplot2::ggsave(paste0(s,".pdf"),p,width=w,height=h,device=grDevices::cairo_pdf);tmp<-tempfile(fileext=".tiff");on.exit(unlink(tmp),add=TRUE);ggplot2::ggsave(tmp,p,width=w,height=h,dpi=600,compression="lzw");if(!file.copy(tmp,paste0(s,".tiff"),overwrite=TRUE))stop("Failed to write TIFF file: ",s)}
.met_device <- function(path,type,w,h){if(type=="pdf")pdf(path,w,h,useDingbats=FALSE)else tiff(path,w,h,units="in",res=600,compression="lzw")}
.met_clean_text <- function(x){x<-trimws(as.character(x));x[x%in%c("","--","NA","N/A","-","Not available")]<-NA_character_;x}
.met_bind_rows <- function(...){x<-list(...);all_names<-unique(unlist(lapply(x,names)));x<-lapply(x,function(z){miss<-setdiff(all_names,names(z));for(n in miss)z[[n]]<-NA;z[,all_names,drop=FALSE]});do.call(rbind,x)}
.met_sanitize_names <- function(x){u<-intToUtf8;keys<-c(u(945),u(946),u(947),u(948),u(916),u(20266),u(23614),u(33085),u(36829),u(34710),u(21348));vals<-c("alpha","beta","gamma","delta","delta","alpha","beta","beta","gamma","delta","+-");x$Name<-as.character(x$Name);for(i in seq_along(keys))x$Name<-gsub(keys[i],vals[i],x$Name,fixed=TRUE);x}
.met_pal<-c(teal="#1F5A6B",rust="#C65D3B",gold="#D6A84B",ink="#263238",grey="#8A9499",grid="#D9DEDF",pale="#F2F5F4",teal_light="#BFD6DA")
.met_class_cols<-c("Organic acids and derivatives"="#A9C9BE","Lipids and lipid-like molecules"="#5F9CA5","Phenylpropanoids and polyketides"="#D7B66F","Organoheterocyclic compounds"="#9ABFC9","Benzenoids"="#D89261","Organic nitrogen compounds"="#8C7A69","Nucleosides, nucleotides, and analogues"="#7D8FA6","Organic oxygen compounds"="#B7C9D4","Alkaloids and derivatives"="#9D87A8")
.met_theme<-function(base_size=10)ggplot2::theme_classic(base_size=base_size,base_family="Arial")+ggplot2::theme(text=ggplot2::element_text(colour=.met_pal[["ink"]]),axis.line=ggplot2::element_line(linewidth=.35,colour=.met_pal[["ink"]]),plot.title=ggplot2::element_text(hjust=.5))

.met_join_mode <- function(raw,meta,mode){
  sc<-paste0(mode,"_",c("S1","S2","S3","H1","H2","H3"));need<-c("Compound_ID","Name","Formula","RT [min]","mzCloud_Results",sc)
  if(!all(need%in%names(raw)))stop(mode," raw table is missing columns: ",paste(setdiff(need,names(raw)),collapse=", "))
  if(!all(c("Compound_ID","Kegg_ID","HMDB_ID","KEGG_pathway")%in%names(meta)))stop(mode," annotation table is missing required columns.")
  meta_keep<-setdiff(names(meta),c("Compound_ID",intersect(names(meta),setdiff(names(raw),"Compound_ID"))))
  extra<-meta[,c("Compound_ID",meta_keep),drop=FALSE]; dup<-setdiff(intersect(names(extra),names(raw)),"Compound_ID");names(extra)[match(dup,names(extra))]<-paste0("Anno_",dup)
  x<-.met_sanitize_names(merge(raw,extra,by="Compound_ID",all.x=TRUE,sort=FALSE));x$Mode<-mode;x$mean_int<-rowMeans(as.matrix(x[,sc]),na.rm=TRUE);names(x)[match(sc,names(x))]<-paste0("Sample_",c("F1","F2","F3","L1","L2","L3"));x
}

# Stage 01 - 1006/51 dataset
stage_01_metabolite_1006_51 <- function(raw_pos_file,raw_neg_file,meta_pos_file,meta_neg_file,output_dir){
  .met_req(c("readxl","limma","openxlsx"));out<-.met_out(output_dir)
  rp<-.met_xlsx(raw_pos_file);rn<-.met_xlsx(raw_neg_file);mp<-.met_xlsx(meta_pos_file);mn<-.met_xlsx(meta_neg_file)
  total<-.met_bind_rows(.met_join_mode(rn,mn,"neg"),.met_join_mode(rp,mp,"pos"));sc<-paste0("Sample_",c("F1","F2","F3","L1","L2","L3"));for(n in sc)total[[n]]<-as.numeric(total[[n]])
  detected<-apply(total[,sc],1,function(x)sum(x[1:3]>0,na.rm=TRUE)>=2||sum(x[4:6]>0,na.rm=TRUE)>=2);d1<-total[detected,,drop=FALSE]
  d2<-d1[!(grepl("17:0",d1$Name,fixed=TRUE)&d1$mzCloud_Results!="Full match"),,drop=FALSE]
  kegg_col<-if("Kegg_ID"%in%names(d2))"Kegg_ID"else"Anno_Kegg_ID";hmdb_col<-if("HMDB_ID"%in%names(d2))"HMDB_ID"else"Anno_HMDB_ID"
  d2$Standard_ID<-ifelse(!is.na(d2[[kegg_col]])&d2[[kegg_col]]!="--",as.character(d2[[kegg_col]]),ifelse(!is.na(d2[[hmdb_col]])&d2[[hmdb_col]]!="--",as.character(d2[[hmdb_col]]),NA_character_))
  pick_max<-function(x,key){x[!duplicated(x[[key]][order(-x$mean_int)]),,drop=FALSE]}
  with<-d2[!is.na(d2$Standard_ID),,drop=FALSE];with<-with[order(-with$mean_int),];with<-with[!duplicated(with$Standard_ID),]
  without<-d2[is.na(d2$Standard_ID),,drop=FALSE];parts<-split(without,without$Formula,drop=TRUE);parts<-lapply(parts,function(x){if(nrow(x)<=1||all(is.na(x$`RT [min]`)))return(x);x$RT_cluster<-cutree(hclust(dist(x$`RT [min]`),method="single"),h=.2);x<-x[order(-x$mean_int),];x<-x[!duplicated(x$RT_cluster),,drop=FALSE];x$RT_cluster<-NULL;x});clean<-.met_bind_rows(with,do.call(rbind,parts));clean<-clean[order(-clean$mean_int),];clean<-clean[!duplicated(clean$Name),,drop=FALSE]
  rawmat<-as.matrix(clean[,sc]);storage.mode(rawmat)<-"numeric";rownames(rawmat)<-clean$Name;rawmat[rawmat==0|is.na(rawmat)]<-NA_real_;imp<-apply(rawmat,2,function(x){mn<-min(x,na.rm=TRUE);x[is.na(x)]<-mn/2;x});ref<-apply(imp,1,median);fac<-apply(sweep(imp,1,ref,"/"),2,median);logmat<-log2(sweep(imp,2,fac,"/")+1)
  design<-cbind(F=c(1,1,1,0,0,0),L=c(0,0,0,1,1,1));fit<-limma::lmFit(logmat,design);fit<-limma::contrasts.fit(fit,limma::makeContrasts(F-L,levels=design));fit<-limma::eBayes(fit)
  all<-limma::topTable(fit,coef=1,number=Inf,sort.by="P");all$Name<-rownames(all);all<-merge(clean[,c("Compound_ID","Name","Formula","Standard_ID","Mode")],all,by="Name",all.y=TRUE,sort=FALSE);dem<-all[all$P.Value<.01&abs(all$logFC)>1,,drop=FALSE];dem$Direction<-ifelse(dem$logFC>0,"Up_in_F","Up_in_L")
  if(nrow(rn)!=472L||nrow(rp)!=624L||nrow(total)!=1096L||nrow(d2)!=1086L||nrow(clean)!=1006L||nrow(dem)!=51L||sum(dem$Direction=="Up_in_F")!=31L||sum(dem$Direction=="Up_in_L")!=20L)stop(sprintf("Metabolomics checkpoint failed: %d -> %d -> %d -> %d; Up_in_F/Up_in_L = %d/%d",nrow(total),nrow(d2),nrow(clean),nrow(dem),sum(dem$Direction=="Up_in_F"),sum(dem$Direction=="Up_in_L")))
  colnames(logmat)<-c("F1","F2","F3","L1","L2","L3");expr<-cbind(clean,data.frame(logmat,check.names=FALSE));expr<-expr[match(rownames(logmat),expr$Name),]
  audit<-data.frame(Step=c("raw_negative","raw_positive","raw_total","after_detection_filter","after_conditional_17_0_rule","cleaned_after_three_level_deduplication","final_DEMs"),Features=c(nrow(rn),nrow(rp),nrow(total),nrow(d1),nrow(d2),nrow(clean),nrow(dem)))
  .met_pair(expr,file.path(out,"cleaned_1006_metabolites"));.met_pair(all,file.path(out,"all_limma_results"));.met_pair(dem,file.path(out,"DEM51"));.met_pair(audit,file.path(out,"metabolomics_flow_audit"));invisible(list(cleaned=expr,all=all,dem51=dem,audit=audit))
}

# Stage 02 - Fig.3A-B
stage_02_fig3ab <- function(cleaned_1006_csv,all_limma_csv,dem51_csv,output_dir){
  .met_req(c("ggplot2","ggrepel","openxlsx"));out<-.met_out(output_dir);x<-.met_csv(cleaned_1006_csv);all<-.met_csv(all_limma_csv);dem<-.met_csv(dem51_csv);sc<-c("F1","F2","F3","L1","L2","L3")
  if(nrow(x)!=1006L||!all(sc%in%names(x)))stop("Input must be the cleaned 1006-metabolite table from Stage 01.")
  mat<-as.matrix(x[,sc]);storage.mode(mat)<-"numeric";rownames(mat)<-x$Compound_ID;pc<-prcomp(t(mat),center=TRUE,scale.=TRUE);pv<-100*pc$sdev^2/sum(pc$sdev^2);scores<-data.frame(Sample=rownames(pc$x),Group=sub("[0-9]+$","",rownames(pc$x)),PC1=pc$x[,1],PC2=pc$x[,2]);cent<-aggregate(cbind(PC1,PC2)~Group,scores,mean);.met_pair(scores,file.path(out,"Fig3A_PCA_scores"))
  scores$cx<-cent$PC1[match(scores$Group,cent$Group)];scores$cy<-cent$PC2[match(scores$Group,cent$Group)];p1<-ggplot2::ggplot(scores,ggplot2::aes(PC1,PC2,colour=Group))+ggplot2::geom_segment(ggplot2::aes(xend=cx,yend=cy),linewidth=.45,alpha=.45,show.legend=FALSE)+ggplot2::geom_point(size=4,shape=21,fill="white",stroke=1.15)+ggrepel::geom_text_repel(ggplot2::aes(label=Sample),size=3,family="Arial",seed=20260726,segment.size=.25,show.legend=FALSE)+ggplot2::scale_colour_manual(values=c(F=.met_pal[["rust"]],L=.met_pal[["teal"]]))+ggplot2::labs(title="Metabolite PCA",x=sprintf("PC1 (%.1f%%)",pv[1]),y=sprintf("PC2 (%.1f%%)",pv[2]),colour=NULL)+.met_theme()+ggplot2::theme(legend.position="bottom")
  all$Status<-"Not_significant";ix<-match(all$Compound_ID,dem$Compound_ID);all$Status[!is.na(ix)]<-ifelse(dem$logFC[ix[!is.na(ix)]]>0,"Up_in_F","Up_in_L");all$neglog10P<--log10(pmax(all$P.Value,.Machine$double.xmin));labs<-do.call(rbind,lapply(split(dem,dem$Direction),function(z)head(z[order(z$P.Value,z$adj.P.Val,-abs(z$logFC),z$Compound_ID),],3)));labs$Label<-vapply(labs$Name,function(z)paste(strwrap(z,27),collapse="\n"),character(1));labs$neglog10P<--log10(pmax(labs$P.Value,.Machine$double.xmin));p2<-ggplot2::ggplot(all,ggplot2::aes(logFC,neglog10P))+ggplot2::geom_vline(xintercept=c(-1,1),linetype="dashed",linewidth=.3,colour=.met_pal[["grey"]])+ggplot2::geom_hline(yintercept=2,linetype="dashed",linewidth=.3,colour=.met_pal[["grey"]])+ggplot2::geom_point(data=all[all$Status=="Not_significant",],colour=.met_pal[["grid"]],size=.65,alpha=.7)+ggplot2::geom_point(data=all[all$Status!="Not_significant",],ggplot2::aes(colour=Status),size=1.5,alpha=.9)+ggrepel::geom_text_repel(data=labs,ggplot2::aes(label=Label),family="Arial",size=2.25,seed=20260716,max.overlaps=Inf,box.padding=.45,point.padding=.2,force=4,min.segment.length=0,segment.size=.25)+ggplot2::scale_colour_manual(values=c(Up_in_F=.met_pal[["rust"]],Up_in_L=.met_pal[["teal"]]),labels=c(Up_in_F="Up",Up_in_L="Down"),name=NULL)+ggplot2::labs(title="Differential metabolites",x=expression(log[2]*" fold change"),y=expression(-log[10](P)))+.met_theme()+ggplot2::theme(legend.position="bottom")
  .met_save(p1,file.path(out,"Fig3A"),6.5,5);.met_save(p2,file.path(out,"Fig3B"),6.5,5);invisible(list(pca=scores,volcano=all))
}

.met_coalesce_columns <- function(x,candidates){cols<-candidates[candidates%in%names(x)];if(!length(cols))return(rep(NA_character_,nrow(x)));out<-rep(NA_character_,nrow(x));for(n in cols){v<-.met_clean_text(x[[n]]);take<-is.na(out)&!is.na(v);out[take]<-v[take]};out}

# Stage 03 - Fig.3C-D
stage_03_fig3cd <- function(cleaned_1006_csv,output_dir,top_subclasses=15){
  .met_req(c("ggplot2","openxlsx"));out<-.met_out(output_dir);x<-.met_csv(cleaned_1006_csv);if(nrow(x)!=1006L)stop("Input must contain 1006 metabolites.")
  x$Superclass<-.met_coalesce_columns(x,c("Class_I","SuperClass(HMDB)","Anno_SuperClass(HMDB)"));x$Subclass<-.met_coalesce_columns(x,c("Class_II","Class(HMDB)","Anno_Class(HMDB)","SubClass(HMDB)","Anno_SubClass(HMDB)"));classified<-x[!is.na(x$Superclass)&!is.na(x$Subclass),,drop=FALSE];if(nrow(classified)!=635L)stop("Expected 635 metabolites with both superclass and subclass annotations, got: ",nrow(classified));s<-aggregate(Compound_ID~Superclass,classified,function(z)length(unique(z)));names(s)[2]<-"Count";s<-s[order(-s$Count),];s$Percent<-100*s$Count/sum(s$Count);s$LegendLabel<-sprintf("%s - %d (%.1f%%)",s$Superclass,s$Count,s$Percent);s$Superclass<-factor(s$Superclass,levels=s$Superclass);u<-aggregate(Compound_ID~Superclass+Subclass,classified,function(z)length(unique(z)));names(u)[3]<-"Count";u<-u[order(-u$Count,u$Subclass),];cutoff<-u$Count[min(top_subclasses,nrow(u))];up<-u[u$Count>=cutoff,];up<-up[order(up$Count,up$Subclass),];up$Subclass<-factor(up$Subclass,levels=up$Subclass)
  .met_pair(s,file.path(out,"Fig3C_superclass_counts"));.met_pair(u,file.path(out,"Fig3D_subclass_counts"));labels<-setNames(s$LegendLabel,as.character(s$Superclass));p1<-ggplot2::ggplot(s,ggplot2::aes(x="",y=Count,fill=Superclass))+ggplot2::geom_col(width=1,color="white",linewidth=.6)+ggplot2::coord_polar(theta="y",start=-pi/2,direction=-1)+ggplot2::geom_text(ggplot2::aes(label=ifelse(Percent>=4,sprintf("%.1f%%",Percent),"")),position=ggplot2::position_stack(vjust=.5),size=3)+ggplot2::scale_fill_manual(values=.met_class_cols,labels=labels,name="Superclass")+ggplot2::theme_void(base_family="Arial")+ggplot2::theme(legend.position="bottom",legend.text=ggplot2::element_text(size=7),legend.title=ggplot2::element_text(size=8))+ggplot2::guides(fill=ggplot2::guide_legend(ncol=2,byrow=TRUE));p2<-ggplot2::ggplot(up,ggplot2::aes(Count,Subclass,fill=Superclass))+ggplot2::geom_col(width=.72)+ggplot2::geom_text(ggplot2::aes(label=Count),hjust=-.2,size=2.7)+ggplot2::scale_fill_manual(values=.met_class_cols,guide="none")+ggplot2::scale_x_continuous(expand=ggplot2::expansion(mult=c(0,.15)))+ggplot2::labs(x="Number of metabolites",y=NULL)+.met_theme(8)+ggplot2::theme(panel.grid.major.x=ggplot2::element_line(colour=.met_pal[["grid"]]),axis.line.y=ggplot2::element_blank())
  .met_save(p1,file.path(out,"Fig3C"),7,6);.met_save(p2,file.path(out,"Fig3D"),7,6);invisible(list(superclass=s,subclass=u))
}

# Stage 04 - Fig.4A
stage_04_fig4a <- function(cleaned_1006_csv,dem51_csv,output_dir){
  .met_req(c("openxlsx","ggplot2"));out<-.met_out(output_dir);x<-.met_csv(cleaned_1006_csv);d<-.met_csv(dem51_csv);sc<-c("F1","F2","F3","L1","L2","L3");i<-match(d$Compound_ID,x$Compound_ID);if(nrow(d)!=51L||anyNA(i))stop("51 DEMs do not match the 1006-metabolite matrix.")
  m<-as.matrix(x[i,sc]);storage.mode(m)<-"numeric";rownames(m)<-d$Name;z<-t(scale(t(m)));z[!is.finite(z)]<-0;ord<-hclust(dist(z))$order;z<-z[rev(ord),,drop=FALSE];.met_pair(data.frame(Metabolite=rownames(z),z,check.names=FALSE),file.path(out,"Fig4A_Z_scores"));long<-data.frame(Metabolite=rep(seq_len(nrow(z)),times=ncol(z)),Sample=rep(sc,each=nrow(z)),Z=as.vector(z));long$Sample<-factor(long$Sample,levels=sc);p<-ggplot2::ggplot(long,ggplot2::aes(Sample,Metabolite,fill=pmax(pmin(Z,2.5),-2.5)))+ggplot2::geom_tile()+ggplot2::scale_fill_gradient2(low=.met_pal[["teal"]],mid="white",high=.met_pal[["rust"]],midpoint=0,limits=c(-2.5,2.5),name="Row z")+ggplot2::scale_y_continuous(expand=c(0,0),breaks=NULL)+ggplot2::scale_x_discrete(expand=c(0,0))+ggplot2::labs(title="DEM abundance patterns",x=NULL,y="Metabolites")+.met_theme()+ggplot2::theme(axis.line=ggplot2::element_blank(),axis.ticks.y=ggplot2::element_blank(),panel.border=ggplot2::element_rect(fill=NA,colour=.met_pal[["ink"]]),legend.position="right");.met_save(p,file.path(out,"Fig4A"),6.3,7);invisible(z)
}

.met_annotation <- function(pos,neg){a<-.met_bind_rows(.met_xlsx(neg),.met_xlsx(pos));need<-c("Compound_ID","Kegg_ID","KEGG_pathway","HMDB_ID");if(!all(need%in%names(a)))stop("Raw annotation tables are missing required KEGG fields.");a$Compound_ID<-as.character(a$Compound_ID);a}
.met_pathways <- function(x,name_col){
  rows<-strsplit(ifelse(is.na(x$KEGG_pathway),"",as.character(x$KEGG_pathway)),";",fixed=TRUE);n<-lengths(rows);y<-data.frame(Compound_ID=rep(x$Compound_ID,n),Metabolite=rep(x[[name_col]],n),entry=trimws(unlist(rows)),stringsAsFactors=FALSE);y<-y[grepl("map[0-9]+",y$entry),];y$pathway_id<-sub(".*?(map[0-9]+).*","\\1",y$entry);y$pathway_name<-trimws(sub("^.*?map[0-9]+\\s*","",y$entry));y$pathway_name<-trimws(sub("^[0-9]{4}\\s+","",y$pathway_name));unique(y[,c("Compound_ID","Metabolite","pathway_id","pathway_name")])
}

# Stage 05 - Fig.4B
stage_05_fig4b <- function(dem51_csv,cleaned_1006_csv,meta_pos_file,meta_neg_file,output_dir){
  .met_req(c("readxl","openxlsx","ggplot2"));out<-.met_out(output_dir);d<-.met_csv(dem51_csv);b<-.met_csv(cleaned_1006_csv);if(nrow(d)!=51L||nrow(b)!=1006L)stop("Input must be the official Stage 01 51/1006 tables.")
  a<-.met_annotation(meta_pos_file,meta_neg_file);a<-a[!duplicated(a$Compound_ID),];a<-a[,intersect(c("Compound_ID","Kegg_ID","KEGG_pathway","HMDB_ID","Lipidmaps_ID"),names(a)),drop=FALSE];b$Compound_ID<-as.character(b$Compound_ID);d$Compound_ID<-as.character(d$Compound_ID);bg<-merge(b[,c("Compound_ID","Name")],a,by="Compound_ID");fg<-merge(d,a,by="Compound_ID");bp<-.met_pathways(bg,"Name");fp<-.met_pathways(fg,"Name")
  N<-length(unique(bp$Compound_ID));n<-length(unique(fp$Compound_ID));ids<-unique(fp$pathway_id);res<-do.call(rbind,lapply(ids,function(id){f<-fp[fp$pathway_id==id,];bb<-bp[bp$pathway_id==id,];k<-length(unique(f$Compound_ID));M<-length(unique(bb$Compound_ID));data.frame(pathway_id=id,pathway_name=f$pathway_name[1],Hits=k,Bg_Hits=M,Total_Foreground=n,Total_Background=N,Pvalue=phyper(k-1,M,N-M,n,lower.tail=FALSE),Hit_Compounds=paste(sort(unique(f$Compound_ID)),collapse="/"),Hit_Names=paste(sort(unique(f$Metabolite)),collapse="; "))}));res$FDR<-p.adjust(res$Pvalue,"BH");res$EnrichmentFactor<-(res$Hits/res$Total_Foreground)/(res$Bg_Hits/res$Total_Background);res<-res[order(res$Pvalue),]
  detail<-merge(fp,d[,c("Compound_ID","logFC","P.Value","adj.P.Val","Direction")],by="Compound_ID",all.x=TRUE);if(N!=245L||n!=9L||nrow(res)!=19L)stop(sprintf("KEGG annotation checkpoint failed: background=%d, foreground=%d, pathways=%d.",N,n,nrow(res)))
  .met_pair(res,file.path(out,"Fig4B_KEGG_enrichment"));.met_pair(detail,file.path(out,"Fig4B_KEGG_metabolite_hits"));if(sum(res$Pvalue<.05)!=5L)stop("Expected 5 nominally significant pathways for Fig.4B.");plot<-head(res,10);plot$pathway_name<-factor(plot$pathway_name,levels=plot$pathway_name[order(plot$EnrichmentFactor,-plot$Pvalue,as.character(plot$pathway_name))]);plot$fdr<-plot$FDR<.05;p<-ggplot2::ggplot(plot,ggplot2::aes(EnrichmentFactor,pathway_name))+ggplot2::geom_segment(ggplot2::aes(x=0,xend=EnrichmentFactor,yend=pathway_name),colour=.met_pal[["grid"]],linewidth=.6)+ggplot2::geom_point(ggplot2::aes(size=Hits,fill=-log10(Pvalue),colour=fdr),shape=21,stroke=1.1)+ggplot2::scale_fill_gradient(low=.met_pal[["teal_light"]],high=.met_pal[["rust"]],name=expression(-log[10](P)))+ggplot2::scale_colour_manual(values=c(`TRUE`=.met_pal[["ink"]],`FALSE`="white"),guide="none")+ggplot2::scale_size_continuous(range=c(3,8),name="Metabolites")+ggplot2::labs(title="Metabolite KEGG enrichment",x="Fold enrichment",y=NULL)+.met_theme()+ggplot2::theme(axis.text.y=ggplot2::element_text(size=8),legend.position="right");.met_save(p,file.path(out,"Fig4B"),7.6,6);invisible(list(enrichment=res,detail=detail))
}
